import { useMemo, useState } from 'react';
import {
  Box,
  Stack,
  Chip,
  Text,
  ProgressCircle,
  Badge,
  Button,
  EmptyState,
  Pagination,
} from '@jinx-ui/react';

type ProjectStatus = 'ok' | 'warning' | 'exceeded';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Marketing Site', quotaPercent: 42, status: 'ok' },
  { id: 'p2', name: 'Analytics Pipeline', quotaPercent: 78, status: 'warning' },
  { id: 'p3', name: 'Mobile App API', quotaPercent: 95, status: 'warning' },
  { id: 'p4', name: 'Internal Tools', quotaPercent: 21, status: 'ok' },
  { id: 'p5', name: 'Billing Service', quotaPercent: 112, status: 'exceeded' },
  { id: 'p6', name: 'Notification Hub', quotaPercent: 60, status: 'ok' },
  { id: 'p7', name: 'Search Index', quotaPercent: 88, status: 'warning' },
  { id: 'p8', name: 'Data Warehouse', quotaPercent: 130, status: 'exceeded' },
  { id: 'p9', name: 'Auth Gateway', quotaPercent: 35, status: 'ok' },
  { id: 'p10', name: 'Media Storage', quotaPercent: 70, status: 'ok' },
  { id: 'p11', name: 'Chat Service', quotaPercent: 55, status: 'ok' },
  { id: 'p12', name: 'Recommendation Engine', quotaPercent: 101, status: 'exceeded' },
];

const STATUS_LABELS: Record<ProjectStatus, string> = {
  ok: 'В норме',
  warning: 'Близко к лимиту',
  exceeded: 'Превышена',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  ok: 'success',
  warning: 'warning',
  exceeded: 'danger',
};

const ALL_STATUSES: ProjectStatus[] = ['ok', 'warning', 'exceeded'];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));

  const pagedProjects = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return filteredProjects.slice(start, start + PAGE_SIZE);
  }, [filteredProjects, page]);

  return (
    <Box className="jx-p-6" style={{ maxWidth: 640 }}>
      <Text as="h2" className="jx-text-lg jx-font-semibold jx-mb-4">
        Расход по проектам
      </Text>

      <Stack direction="row" gap="sm" wrap className="jx-mb-4">
        {ALL_STATUSES.map((status) => {
          const isActive = activeStatuses.includes(status);
          return (
            <Chip
              key={status}
              tone={STATUS_TONES[status]}
              selected={isActive}
              onDismiss={isActive ? () => toggleStatus(status) : undefined}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_LABELS[status]}
            </Chip>
          );
        })}
      </Stack>

      {filteredProjects.length === 0 ? (
        <EmptyState
          title="Нет проектов по выбранным фильтрам"
          description="Попробуйте изменить или сбросить фильтры статуса."
          action={
            <Button variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </Button>
          }
        />
      ) : (
        <>
          <Stack direction="column" gap="none" className="jx-divide-y">
            {pagedProjects.map((project) => (
              <Stack
                key={project.id}
                direction="row"
                align="center"
                justify="space-between"
                gap="md"
                className="jx-py-3"
              >
                <Text className="jx-font-medium" style={{ flex: 1 }}>
                  {project.name}
                </Text>

                <Stack direction="row" align="center" gap="sm">
                  <ProgressCircle
                    value={Math.min(project.quotaPercent, 100)}
                    size="sm"
                    tone={STATUS_TONES[project.status]}
                    label={`${project.quotaPercent}%`}
                  />
                  <Badge tone={STATUS_TONES[project.status]}>
                    {STATUS_LABELS[project.status]}
                  </Badge>
                </Stack>
              </Stack>
            ))}
          </Stack>

          {totalPages > 1 && (
            <Stack direction="row" justify="center" className="jx-mt-4">
              <Pagination
                page={page}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            </Stack>
          )}
        </>
      )}
    </Box>
  );
}

